import os
import json
from pathlib import Path

# Read both policy documents
policy_files = []
for file in os.listdir('.'):
    if file.endswith('.json') and 'policy' in file.lower():
        policy_files.append(file)

print(f"Found policy files: {policy_files}")

policies = {}
for policy_file in policy_files:
    try:
        with open(policy_file, 'r', encoding='utf-8') as f:
            policies[policy_file] = json.load(f)
        print(f"Successfully loaded {policy_file}")
    except Exception as e:
        print(f"Error loading {policy_file}: {e}")

# Analyze policies to determine authoritative one
if len(policies) == 0:
    print("No policy documents found")
elif len(policies) == 1:
    print(f"Only one policy found: {list(policies.keys())[0]}")
    print("This is the authoritative policy by default")
else:
    print("\nAnalyzing multiple policies to determine authoritative one...")

    # Check for metadata indicating authority
    authoritative_policy = None
    authority_indicators = []

    for filename, policy_data in policies.items():
        indicators = []

        # Check for explicit authority indicators
        if isinstance(policy_data, dict):
            # Check for version numbers
            if 'version' in policy_data:
                indicators.append(f"has version: {policy_data['version']}")

            # Check for effective dates
            if 'effective_date' in policy_data:
                indicators.append(f"effective date: {policy_data['effective_date']}")

            # Check for approval status
            if 'approved' in policy_data and policy_data['approved']:
                indicators.append("explicitly approved")

            # Check for document type
            if 'document_type' in policy_data:
                doc_type = policy_data['document_type'].lower()
                if 'master' in doc_type or 'primary' in doc_type or 'authoritative' in doc_type:
                    indicators.append(f"document type indicates authority: {doc_type}")

        authority_indicators.append((filename, indicators))

    # Display findings
    print("\nAuthority indicators found:")
    for filename, indicators in authority_indicators:
        print(f"\n{filename}:")
        if indicators:
            for indicator in indicators:
                print(f"  - {indicator}")
        else:
            print("  No clear authority indicators found")

    # Determine authoritative policy based on indicators
    # Look for the most recent version or explicit authority markers
    authoritative_candidates = []

    for filename, indicators in authority_indicators:
        score = 0
        for indicator in indicators:
            if 'explicitly approved' in indicator:
                score += 3
            if 'document type indicates authority' in indicator:
                score += 2
            if 'version' in indicator:
                # Higher version numbers get higher scores
                try:
                    version_str = indicator.split(': ')[1]
                    # Simple version parsing - could be improved
                    if '.' in version_str:
                        version_parts = version_str.split('.')
                        score += float(version_parts[0]) + float(version_parts[1])/10
                except:
                    pass

        authoritative_candidates.append((filename, score))

    # Sort by score
    authoritative_candidates.sort(key=lambda x: x[1], reverse=True)

    print(f"\nAuthority scores:")
    for filename, score in authoritative_candidates:
        print(f"{filename}: {score}")

    if authoritative_candidates[0][1] > 0:
        authoritative_policy = authoritative_candidates[0][0]
        print(f"\nDetermined authoritative policy: {authoritative_policy}")
    else:
        print("\nCould not determine authoritative policy based on content")
        print("Using the most recently modified file as fallback...")

        # Fallback: use most recently modified file
        file_mod_times = []
        for filename in policies.keys():
            mod_time = os.path.getmtime(filename)
            file_mod_times.append((filename, mod_time))

        file_mod_times.sort(key=lambda x: x[1], reverse=True)
        authoritative_policy = file_mod_times[0][0]
        print(f"Most recently modified: {authoritative_policy}")

    print(f"\nAuthoritative policy document: {authoritative_policy}")
    print(f"Policy content preview: {json.dumps(policies[authoritative_policy], indent=2)[:500]}...")
